with matched as (select e.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from orders e inner join promotions pr on e.channel = pr.channel and e.order_date >= pr.starts_on and e.order_date <= date_add(pr.ends_on, 7)) select case when promo_id >= 10 then 'LARGE' else 'SMALL' end as promo_id_tier, date_trunc('week', order_date) as week_start, date_trunc('month', order_date) as activity_month, max(shipping_fee) as max_shipping_fee, round(avg(discount_pct), 2) as avg_discount_pct, stddev_samp(amount) as amount_stddev from matched group by case when promo_id >= 10 then 'LARGE' else 'SMALL' end, date_trunc('week', order_date), date_trunc('month', order_date);
